'use strict';
function statusDonut(rows,mode){
 const counts=Analytics.countStatus(rows),entries=Object.entries(counts).filter(([,n])=>n),circ=2*Math.PI*58;let offset=0;
 const rings=entries.map(([k,n])=>{const len=n/rows.length*circ,part=`<a href="#results" data-cohort="${mode}" data-drill-status="${esc(k)}" aria-label="${esc(Plan.labels[k]||k)}: ${n} rows in ${esc(Analytics.scopes[mode].title)}"><circle cx="80" cy="80" r="58" fill="none" stroke="${colors[k]||'#8493a8'}" stroke-width="23" stroke-dasharray="${Math.max(0,len-(entries.length>1?2:0))} ${circ}" stroke-dashoffset="${-offset}" transform="rotate(-90 80 80)"><title>${esc(Plan.labels[k]||k)}: ${n} (${Math.round(n/rows.length*100)}%)</title></circle></a>`;offset+=len;return part}).join('');
 return `<div class="donut-wrap"><svg class="donut" viewBox="0 0 160 160" role="group" aria-label="Status distribution for ${esc(Analytics.scopes[mode].title)}"><circle cx="80" cy="80" r="58" fill="none" stroke="#edf1f6" stroke-width="23"/>${rings}<text x="80" y="79" text-anchor="middle" class="donut-number">${rows.length}</text><text x="80" y="100" text-anchor="middle" class="donut-unit">plan rows</text></svg></div><div class="donut-legend">${entries.map(([k,n])=>`<button data-cohort="${mode}" data-drill-status="${esc(k)}"><i style="background:${colors[k]||'#8493a8'}"></i><span>${esc(Plan.labels[k]||k)}</span><b>${n}</b><small>${Math.round(n/rows.length*100)}%</small></button>`).join('')||'<p>No rows in this section.</p>'}</div>`;
}
function stackedBars(rows,key){
 const grouped=Analytics.groupRows(rows,key).sort((a,b)=>b.total-a.total),max=Math.max(1,...grouped.map(g=>g.total));
 return grouped.map(g=>`<div class="bar-item"><div class="bar-top"><button class="bar-label" data-drill-field="${key}" data-drill-value="${esc(g.label)}">${esc(g.label==='Not recorded'&&key==='owner'?'Unassigned':g.label)}</button><strong>${g.total}</strong></div><div class="bar-track"><div class="bar-stack" style="width:${g.total/max*100}%">${Object.entries(g.statuses).filter(([,n])=>n).map(([k,n])=>`<button data-drill-field="${key}" data-drill-value="${esc(g.label)}" data-drill-status="${esc(k)}" style="flex:${n};background:${colors[k]||'#8493a8'}" aria-label="${esc(g.label)}, ${esc(Plan.labels[k]||k)}: ${n}" title="${esc(Plan.labels[k]||k)}: ${n}"></button>`).join('')}</div></div></div>`).join('')||'<p class="empty-chart">No matching rows.</p>';
}
function smallLegend(){return `<div class="chart-key">${Object.entries(Plan.labels).map(([k,label])=>`<span><i style="background:${colors[k]}"></i>${label}</span>`).join('')}</div>`}
function deadlinesChart(rows){
 const d=Analytics.dueSummary(rows,state.dueField,state.asOf),max=Math.max(1,...d.months.map(m=>m.total));
 return `<div class="chart-heading"><div><h3>Delivery calendar</h3><p>Due dates by month · ${rows.length-d.missing} dated rows</p></div><label><span class="sr-only">Deadline milestone</span><select id="deadline-field"><option value="due" ${state.dueField==='due'?'selected':''}>Feature Done target</option><option value="preDue" ${state.dueField==='preDue'?'selected':''}>Pre-silicon due</option></select></label></div><div class="deadline-toolbar"><label>As of <input id="as-of" type="date" value="${state.asOf}"></label><span>${d.missing} without a usable date</span></div><div class="month-scroll"><div class="month-chart">${d.months.map(m=>`<button class="month-column" data-drill-field="dueMonth" data-drill-value="${m.month}" aria-label="${m.month}: ${m.total} rows, ${m.confirmed} milestone confirmed"><strong>${m.total}</strong><span class="month-space"><span class="month-stack" style="height:${m.total/max*150}px"><i class="unconfirmed" style="flex:${m.unconfirmed}"></i><i class="confirmed" style="flex:${m.confirmed}"></i></span></span><span>${new Date(m.month+'-15T12:00:00').toLocaleDateString('en-GB',{month:'short'})}</span><small>${m.month.slice(0,4)}</small></button>`).join('')||'<p class="empty-chart">No usable due dates in this selection.</p>'}</div></div><div class="chart-key"><span><i style="background:#137e78"></i>Milestone confirmed</span><span><i style="background:#9daed0"></i>Completion unconfirmed</span></div><button class="date-attention" data-attention="past">${d.past.length} past due date with completion unconfirmed <span>View rows →</span></button><p class="chart-footnote">Counts use workbook statuses, not live Jira. For pre-silicon, P-D and Done confirm completion; for B0, only Done does.</p>`;
}
function documentMatrix(){const docs=data.rows.filter(Analytics.scopes.docs.match),groups=Analytics.groupRows(docs,'group');return `<div class="chart-heading"><div><h3>Development specification matrix</h3><p>Workbook-wide · ${docs.length} document rows · click a recorded document for details</p></div><button class="text-button" data-cohort="docs">View documents →</button></div><div class="table-scroll"><table class="doc-matrix"><thead><tr><th>Component / document group</th><th>SRS</th><th>SAD</th><th>SUD</th><th>Other</th></tr></thead><tbody>${groups.map(g=>`<tr><th scope="row">${esc(g.label)}<span class="subline">${[...new Set(g.rows.map(r=>r.team).filter(Boolean))].map(esc).join(' / ')}</span></th>${['SRS','SAD','SUD','Other'].map(t=>{const list=g.rows.filter(r=>Analytics.docType(r.title)===t);return `<td>${list.map(r=>`<button data-row="${r.row}" class="matrix-status" title="${esc(r.title)} · ${esc(r.key)}">${badge(r)}<small>${esc(r.key)||'Row '+r.row}</small></button>`).join('')||'<span class="no-doc">No row</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><p class="chart-footnote">SRS: requirements · SAD: architecture · SUD: unit design. “No row” means no matching entry in this section; it does not establish that a document is missing.</p>`}
function renderDashboard(rows){const areaKey=new Set(rows.map(r=>r.section)).size>1?'section':'group';return `<div class="visual-dashboard">${intelligenceBanner()}<div class="dashboard-section-heading"><h3>Workbook overview</h3><p>Complete section totals · select a status or section to open its rows</p></div><div class="cohort-grid">${['focus','req','docs','validation'].map(mode=>`<article class="chart-card cohort ${state.mode===mode?'current':''}"><div class="chart-heading"><button data-cohort="${mode}" class="cohort-title">${Analytics.scopes[mode].title} <span>↗</span></button></div><p class="cohort-subtitle">${Analytics.scopes[mode].subtitle}</p>${statusDonut(data.rows.filter(Analytics.scopes[mode].match),mode)}</article>`).join('')}</div><div class="dashboard-section-heading selected-scope"><h3>Selected scope: ${esc(Analytics.scopes[state.mode].title)}</h3><p>${rows.length} rows after filters · click a bar to inspect its rows</p></div>${smallLegend()}<div class="analysis-grid"><article class="chart-card"><div class="chart-heading"><div><h3>Status by ${areaKey==='section'?'feature area':'component'}</h3><p>Plan rows · source statuses</p></div></div><div class="bar-list">${stackedBars(rows,areaKey)}</div></article><article class="chart-card"><div class="chart-heading"><div><h3>Team ownership</h3><p>Plan rows by team · TT remains separate from BOS teams</p></div></div><div class="bar-list">${stackedBars(rows,'team')}</div></article><article class="chart-card deadline-card">${deadlinesChart(rows)}</article><article class="chart-card"><div class="chart-heading"><div><h3>Assignee distribution</h3><p>Row counts, not effort estimates · includes unassigned rows</p></div></div><div class="bar-list owner-bars">${stackedBars(rows,'owner')}</div></article><article class="chart-card matrix-card">${documentMatrix()}</article></div><p class="chart-footnote dashboard-source">Visual reference: <a href="https://bos-semi.atlassian.net/jira/dashboards/12467" target="_blank" rel="noopener noreferrer">Eagle-N B0 Host Software Development ↗</a>. Charts here count workbook rows; Jira uses its own filters and statuses.</p></div>`;}
document.addEventListener('click',e=>{
 const cohort=e.target.closest('[data-cohort]'),drill=e.target.closest('[data-drill-field]'),attention=e.target.closest('[data-attention]');
 if(cohort){e.preventDefault();Object.assign(state,{mode:cohort.dataset.cohort,category:'',query:'',team:'',status:cohort.dataset.drillStatus||'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0,view:'register'});controls();render();document.querySelector('.workspace').scrollIntoView({block:'start'});}
 if(drill){e.preventDefault();const key=drill.dataset.drillField;if(['section','group','team','owner','dueMonth'].includes(key)){state[key]=drill.dataset.drillValue;if(drill.dataset.drillStatus)state.status=drill.dataset.drillStatus;state.page=0;state.view='register';controls();render();}}
 if(attention){state.attention='past';state.page=0;state.view='register';controls();render();}
});
document.addEventListener('change',e=>{if(e.target.id==='deadline-field'){state.dueField=e.target.value;state.dueMonth='';state.attention='';render()}if(e.target.id==='as-of'&&Analytics.isDate(e.target.value)){state.asOf=e.target.value;render()}});
